components.css:
.ds-primary-button {
  background: var(--green, #484b35);
  color: var(--theme-field, #f7f1e3);
  border: 1px solid transparent;
  border-radius: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 12px 18px;
  font-size: 12px;
  white-space: nowrap;
}
.ds-primary-button:hover:not(:disabled) {
  background: var(--ink, #2d2c25);
}

.ds-primary-button {cursor: pointer; transition: background .16s, color .16s, border-color .16s;} .ds-primary-button:focus-visible {outline: 3px solid #b9802c; outline-offset: 4px;} .ds-primary-button:disabled {opacity: .45; cursor: not-allowed;} @media(prefers-reduced-motion: reduce) {.ds-primary-button {animation: none; transition: none;}} .ds-primary-button {font-family: "IBM Plex Sans", sans-serif;}

.ds-text-button {
  border: 0;
  background: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 4px 0;
  font-size: 12px;
}
.ds-text-button:hover:not(:disabled) {
  color: #996421;
}

.ds-text-button {cursor: pointer; transition: background .16s, color .16s, border-color .16s;} .ds-text-button:focus-visible {outline: 3px solid #b9802c; outline-offset: 4px;} .ds-text-button:disabled {opacity: .45; cursor: not-allowed;} @media(prefers-reduced-motion: reduce) {.ds-text-button {animation: none; transition: none;}} .ds-text-button {font-family: "IBM Plex Sans", sans-serif; color: var(--ink, #2d2c25);} .ds-text-button:hover:not(:disabled) {color: #996421;}

.ds-message-columns textarea {
  width: 100%;
  height: 112px;
  background: var(--theme-field, #f7f1e3);
  border: 1px solid var(--line, #b6ad96);
  border-radius: 1px;
  margin-top: 9px;
  padding: 13px 15px;
  resize: vertical;
  line-height: 1.75;
  font-family: "Special Elite", monospace;
  font-size: 16px;
  letter-spacing: 0.055em;
  word-break: break-all;
  color: var(--ink, #2d2c25);
}

.ds-message-columns textarea {font-family: "Special Elite", monospace;} .ds-message-columns textarea:focus-visible {outline: 3px solid #b9802c; outline-offset: 4px;}

.ds-validation-badge {
  background: #e0dfc6;
  color: #484b35;
  border-radius: 2px;
  padding: 5px 9px;
  font-size: 10px;
  white-space: nowrap;
}
 .ds-validation-badge {font-family:"IBM Plex Sans", sans-serif;}

.ds-menu-panel {
  border: 1px solid var(--line, #b6ad96);
  background: var(--theme-field, #f7f1e3);
  border-radius: 2px;
  padding: 23px 25px;
}
.ds-muted {
  color: var(--muted, #625e50);
  font-size: 13px;
}
 .ds-menu-panel {color:var(--ink, #2d2c25); font-family:"IBM Plex Sans", sans-serif;} .ds-menu-panel h2 {margin:0; font:500 19px var(--serif, "Oswald", sans-serif); letter-spacing:.01em;}

.ds-machine-key {
  border: 1px solid #a7a58e;
  width: clamp(34px, 3.8vw, 47px);
  height: clamp(34px, 3.8vw, 47px);
  border-radius: 50%;
  background: #161914;
  color: #f3eddc;
  font-family: "Special Elite", monospace;
  font-size: 18px;
  box-shadow: 0 3px 5px #0005;
  flex-shrink: 0;
}
.ds-machine-key:hover:not(:disabled) {
  background: #464b3a;
  border-color: #e6dfcc;
}
.ds-machine-key.ds-pressed {
  border-color: #dfddbd;
  box-shadow: inset 0 2px 5px #061c1860;
}
.ds-machine-key.ds-lit {
  background: var(--amber, #dfb664);
  border-color: var(--amber, #dfb664);
  color: #28271e;
  animation: lamp-on 0.32s cubic-bezier(0.16, 1, 0.3, 1);
}

.ds-machine-key {font-family: "Special Elite", monospace;}
@keyframes lamp-on {from {box-shadow: 0 2px 18px #e9bc6b55;} to {box-shadow: 0 3px 5px #0005;}}
.ds-machine-key {cursor: pointer; transition: background .16s, color .16s, border-color .16s;} .ds-machine-key:focus-visible {outline: 3px solid #b9802c; outline-offset: 4px;} .ds-machine-key:disabled {opacity: .45; cursor: not-allowed;} @media(prefers-reduced-motion: reduce) {.ds-machine-key {animation: none; transition: none;}}

.ds-help-trigger {
  margin: 12px 0;
  font-size: 12px;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  cursor: pointer;
  color: var(--green, #484b35);
  width: fit-content;
  min-height: 36px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  text-align: left;
}
 .ds-help-popup {
  background: var(--paper, #eee7d5);
  color: var(--ink, #2d2c25);
  border-radius: 2px;
  padding: 12px 14px;
  font-size: 13px;
  line-height: 1.7;
  width: 320px;
  max-width: min(320px, calc(100vw - 24px), var(--available-width, 320px));
  max-height: var(--available-height, none);
  overflow-y: auto;
  overflow-wrap: anywhere;
  box-shadow: 0 4px 20px #112c2533;
}
.ds-help-preview {padding: 20px; font-family: "IBM Plex Sans", sans-serif;} .ds-help-trigger {font-family: inherit; margin: 8px 0 0;} .ds-help-trigger svg {flex-shrink: 0;} .ds-help-trigger:hover {text-decoration: underline; text-underline-offset: 3px;} .ds-help-trigger:focus-visible {outline: 3px solid #b9802c; outline-offset: 4px;} @media(max-width: 600px) {.ds-help-trigger {min-height: 44px;}}
.ds-help-trigger {cursor: pointer; transition: background .16s, color .16s, border-color .16s;} .ds-help-trigger:focus-visible {outline: 3px solid #b9802c; outline-offset: 4px;} .ds-help-trigger:disabled {opacity: .45; cursor: not-allowed;} @media(prefers-reduced-motion: reduce) {.ds-help-trigger {animation: none; transition: none;}}
